from mk import *
from lib import fbd
STRICT["on"] = True

def fig():
    g = Fig(560, 300, "מערכת גלגלות: גלגלת קבועה O1 תלויה מהתקרה בחוט S1, וגלגלת ניידת O2. חוט S3 עובר מיד האדם מעל O1, מתחת ל-O2 ועד התקרה. משקולת במסה 100 קילוגרם תלויה מ-O2 בחוט S2 ומונחת על הקרקע. האדם במסה 80 קילוגרם עומד על הקרקע")
    g.ceiling(100, 360, 20)
    g.line(220, 20, 220, 50, width=1.5); g.text(228, 40, "S₁", anchor="start")
    g.pulley(220, 70, 20); g.text(220, 100, "O₁")
    g.line(200, 70, 200, 230, width=1.5); g.text(192, 150, "S₃", anchor="end")
    g.line(240, 70, 240, 150, width=1.5); g.text(248, 120, "S₃", anchor="start")
    g.pulley(260, 160, 20); g.text(260, 190, "O₂")
    g.line(280, 160, 280, 20, width=1.5); g.text(288, 100, "S₃", anchor="start")
    g.line(260, 180, 260, 240, width=1.5); g.text(268, 214, "S₂", anchor="start")
    g.block(260, 260, 70, 34, "M = 100 kg", fill="var(--d-fill)", text_color="var(--d-label)")
    g.ground(80, 400, 277)
    g.person(200, 277, 1.2); g.text(160, 250, "m = 80 kg", anchor="end")
    return g

E(id="bagrut-2004-q2", year=2004, label="2004 שאלה 2", topic="dynamics", sub="dyn-systems", diff=3, fig=fig,
  stem=r"בתרשים מוצגת מערכת שכוללת: גלגלת קבועה שמרכזה $O_1$, גלגלת ניידת שמרכזה $O_2$, שלושה חוטים $S_1$, $S_2$, $S_3$, ומשקולת שמסתה $M = 100\,\text{kg}$ שמונחת על הקרקע. אדם שמסתו $m = 80\,\text{kg}$ עומד על הקרקע ומחזיק את הקצה של החוט $S_3$. אפשר להזניח את מסת הגלגלות והחוטים, ואת החיכוך בצירי הגלגלות.",
  parts=[
    P("א", r"האדם מושך את קצה החוט $S_3$ כלפי מטה בכוח של $100\,\text{N}$. מה גודל הכוח שהאדם מפעיל על הקרקע? מה המתיחות בחוט $S_1$? מה גודל הכוח שהמשקולת מפעילה על הקרקע?", multi((r"הכוח של האדם על הקרקע", 700, "N"), (r"המתיחות בחוט S₁", 200, "N"), (r"הכוח של המשקולת על הקרקע", 800, "N")), ["fbd", "principle"], [
        X(r"כל הגופים במנוחה, ולכן הכוח השקול על כל אחד אפס. בוחרים כלפי מעלה כחיובי. השאלה לא קבעה כיוון. לאורך החוט $S_3$ המתיחות זהה בכל מקום, כי החוט קל והגלגלות בלי חיכוך."),
        D(r"תרשים הכוחות על האדם", lambda: fbd([("T", 90, 0.35, -14), ("N", 90, 1.0, 14), ("mg", -90, 1.15)],
            "תרשים כוחות על האדם: מתיחות החוט כלפי מעלה, הכוח הנורמלי של הקרקע כלפי מעלה, וכוח הכובד כלפי מטה. הכיוון החיובי כלפי מעלה",
            positive=90, body="block", note="במנוחה")),
        S(r"משוואת כוחות לאדם", r"האדם מושך את החוט כלפי מטה, ולכן לפי החוק השלישי החוט מושך אותו כלפי מעלה באותו כוח. גם הקרקע דוחפת אותו כלפי מעלה, והכובד נגדם", r"T + N - mg = 0 \;\Rightarrow\; N = 800 - 100 = 700\,\text{N}", eq=r"\Sigma\vec F = m\vec a"),
        S(r"הכוח של האדם על הקרקע", r"לפי החוק השלישי, שווה בגודלו לכוח הנורמלי והפוך בכיוונו", r"N' = 700\,\text{N}\ \downarrow", eq=r"\vec F_{1,2} = -\vec F_{2,1}"),
        D(r"תרשים הכוחות על הגלגלת הקבועה", lambda: fbd([("S₁", 90, 1.0), ("T", -90, 0.5, -14), ("T", -90, 0.5, 14)],
            "תרשים כוחות על הגלגלת הקבועה: החוט S1 כלפי מעלה, ושני הקטעים של החוט S3 כלפי מטה. הכיוון החיובי כלפי מעלה",
            positive=90, body="ball", note="גלגלת קלה")),
        S(r"משוואת כוחות לגלגלת הקבועה", r"שני קטעים של החוט S₃ יורדים ממנה, וכל אחד מושך כלפי מטה במאה ניוטון", r"S_1 - 2T = 0 \;\Rightarrow\; S_1 = 2 \cdot 100 = 200\,\text{N}"),
        S(r"משוואת כוחות לגלגלת הניידת", r"שני קטעים של החוט S₃ מחזיקים אותה כלפי מעלה, והחוט S₂ מושך אותה כלפי מטה", r"2T - S_2 = 0 \;\Rightarrow\; S_2 = 200\,\text{N}"),
        D(r"תרשים הכוחות על המשקולת", lambda: fbd([("S₂", 90, 0.45, -14), ("N", 90, 1.0, 14), ("Mg", -90, 1.3)],
            "תרשים כוחות על המשקולת: החוט S2 כלפי מעלה, הכוח הנורמלי של הקרקע כלפי מעלה, וכוח הכובד כלפי מטה. הכיוון החיובי כלפי מעלה",
            positive=90, body="block", body_label="M", note="על הקרקע")),
        S(r"משוואת כוחות למשקולת", r"הקרקע משלימה את מה שהחוט לא מחזיק", r"S_2 + N_M - Mg = 0 \;\Rightarrow\; N_M = 1000 - 200 = 800\,\text{N}"),
    ], r"האדם על הקרקע: $700\,\text{N}$. המתיחות בחוט $S_1$: $200\,\text{N}$. המשקולת על הקרקע: $800\,\text{N}$", key=r"700 N ; 200 N ; 800 N"),
    P("ב", r"מה הכוח הקטן ביותר שהאדם צריך למשוך בו את קצה החוט $S_3$, כדי שהמשקולת לא תפעיל כוח על הקרקע?", num(500, "N"), ["fbd", "principle"], [
        S(r"התנאי", r"הכוח הנורמלי על המשקולת מתאפס, והחוט S₂ מחזיק את כל המשקל", r"S_2 - Mg = 0 \;\Rightarrow\; S_2 = 1000\,\text{N}", eq=r"\Sigma\vec F = m\vec a"),
        S(r"הכוח בחוט S₃", r"מהמשוואה של הגלגלת הניידת: החוט S₂ מושך פי שניים מהחוט S₃", r"2T = S_2 \;\Rightarrow\; T = 500\,\text{N}"),
    ], r"$500\,\text{N}$", key=r"500 N"),
    P("ג", r"האדם מושך את קצה החוט $S_3$ בכוח הגדול ביותר שבו הוא עדיין לא מתרומם מהקרקע (כלומר, כמעט לא מפעיל עליה כוח). מה הכוח שהאדם מפעיל על החוט במצב הזה? האם המשקולת מאיצה, ואם כן, מה התאוצה שלה?", multi((r"הכוח של האדם על החוט", 800, "N"), (r"התאוצה של המשקולת (כלפי מעלה)", 6, "m/s^2")), ["fbd", "principle"], [
        S(r"התנאי לאדם", r"הכוח הנורמלי על האדם מתאפס, והחוט מחזיק את כל משקלו", r"T + 0 - mg = 0 \;\Rightarrow\; T = 800\,\text{N}", eq=r"\Sigma\vec F = m\vec a"),
        S(r"הכוח בחוט S₂", r"פי שניים מהחוט S₃, וזה יותר ממשקל המשקולת", r"S_2 = 2 \cdot 800 = 1600\,\text{N} > 1000\,\text{N}"),
        D(r"תרשים הכוחות על המשקולת כשהיא מתרוממת", lambda: fbd([("S₂", 90, 1.3), ("Mg", -90, 0.85)],
            "תרשים כוחות על המשקולת: החוט S2 כלפי מעלה, גדול מכוח הכובד כלפי מטה. אין כוח נורמלי. הכיוון החיובי כלפי מעלה",
            positive=90, body="block", body_label="M", note="מתרוממת")),
        S(r"משוואת כוחות למשקולת", r"בכיוון החיובי פועל החוט, ונגדו הכובד. המשקולת כבר לא על הקרקע", r"S_2 - Mg = Ma", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מחלקים את משוואת הכוחות במסה", r"התאוצה חיובית, כלומר כלפי מעלה", r"a = \frac{1600 - 1000}{100} = 6\,\text{m/s}^2"),
    ], r"הכוח $800\,\text{N}$. כן, המשקולת מאיצה ב-$6\,\text{m/s}^2$ כלפי מעלה", key=r"800 N ; 6 m/s^2 כלפי מעלה"),
  ],
  concepts=["גלגלת קבועה וגלגלת ניידת", "מתיחות", "החוק השלישי של ניוטון", "כוח נורמלי"],
  summary=r"מערכת גלגלות: הגלגלת הניידת מכפילה את הכוח. כמה האדם צריך למשוך, ומה קורה כשהוא מושך כמשקלו.",
  review="הנחה שלי.\nסעיפים א ו-ג הם סעיף אחד כל אחד, כמו במקור, עם כמה תיבות.\nמה לבדוק: רק לאשר.")
